function LookupName(Type, Value)
{
	try
	{
		var theApp = TheApplication();
		var BS = theApp.GetService("MF Common Service");
		var BSInput = theApp.NewPropertySet();
		var BSOutput = theApp.NewPropertySet();
		var x = Value;
		BSInput.SetProperty("Type", Type);
		BSInput.SetProperty("Value", Value);
		BS.InvokeMethod("LookupName", BSInput, BSOutput);
		x = BSOutput.GetProperty("Name");
	}

	catch(e)
	{

	}

	finally
	{
		BSInput = null;
		BSOutput = null;
		BS = null;
		theApp = null;
	}
	return x;
}

function RoleValidation(mId) {
    try {
        var TheApp = TheApplication();
        var mBO = TheApp.GetBusObject("MF Approval Master New BO");
        var mBC = mBO.GetBusComp("MF Approvers");
        var pos = TheApp.GetProfileAttr("Primary Position Type");
        var posType = LookupName("POSITION_TYPE", pos);
        with(mBC) {
            SetViewMode(AllView);
            ClearToQuery();

            SetSearchSpec("MF Master Id", mId);
            SetSearchSpec("MF Approvers", posType);
            SetSearchSpec("Active Flag", "Y");
            ExecuteQuery(ForwardOnly);
            if (!FirstRecord()) {
                TheApplication().RaiseErrorText("Invalid approver selected");
            }
        }
    } catch (e) {

        throw (e);

    } finally {
        mBC = null;
        mBO = null;
        TheApp = null;
    }
}

function ApprovalHistoryCheck(sId) {
    try {
        var TheApp = TheApplication();
        var oAppFlowHistoryBO = TheApp.GetBusObject("MF Approval History");
        var oAppFlowHistoryBC = oAppFlowHistoryBO.GetBusComp("MF Approval Flow History");
        var bcMVF, sExpr = "";
        with(oAppFlowHistoryBC) {
            SetViewMode(AllView);
            ClearToQuery();
            sExpr = "[MF Entity Id] = '" + sId + "' AND [MF Status] = 'Pending for Approval' AND [MF Sequence] = '1'";
            SetSearchExpr(sExpr);
            ExecuteQuery(ForwardOnly);
            if (FirstRecord()) {
                bcMVF = GetMVGBusComp("MFApprovers");
                with(bcMVF) {
                    SetViewMode(AllView);
                    ClearToQuery();
                    ExecuteQuery(ForwardOnly);
                    if (!FirstRecord()) {
                        HistoryRecordDelete(sId);
                        EntityRecordDelete(sId);
                        TheApp.RaiseErrorText("Approvers do not exist for the given position");
                    }
                }
            }
        }
    } catch (e) {
        throw (e);
    } finally {
        bcMVF = null;
        oAppFlowHistoryBC = null;
        oAppFlowHistoryBO = null;
        TheApp = null;
    }
}

function HistoryRecordDelete(sId) {
    try {
        var oAppFlowHistoryBO = TheApplication().GetBusObject("MF Approval History");
        var oAppFlowHistoryBC = oAppFlowHistoryBO.GetBusComp("MF Approval Flow History");
        with(oAppFlowHistoryBC) {
            SetViewMode(AllView);
            ClearToQuery();
            SetSearchExpr("[MF Entity Id] = '" + sId + "'");
            ExecuteQuery(ForwardOnly);
            while (FirstRecord()) {
                DeleteRecord();
            }
        }
    } catch (e) {
        throw (e);
    } finally {
        oAppFlowHistoryBC = null;
        oAppFlowHistoryBO = null;
    }
}

function EntityRecordDelete(sId) {
    try {
        var oAppFlowEntityBC = TheApplication().GetBusObject("MF Approval History").GetBusComp("MF Entity Approval Flow");
        with(oAppFlowEntityBC) {
            ActivateField("Entity Id");
            ActivateField("Status");
            SetViewMode(AllView);
            ClearToQuery();
            SetSearchSpec("Entity Id", sId);
            ExecuteQuery(ForwardOnly);
            while (FirstRecord()) {
                DeleteRecord();
            }
        }
    } catch (e) {
        throw (e);
    } finally {
        oAppFlowEntityBC = null;
    }
}
