		var sAssLIC1 = TheApplication().InvokeMethod("LookupValue","SR_AREA","Trade-In");
		var sAssLIC2 = TheApplication().InvokeMethod("LookupValue","SR_AREA","UV Trade-In");

		var sAccId = this.BusComp().GetFieldValue("MF Account Id");
		var oaBO = TheApplication().GetBusObject("Account");
		var oapBC = oaBO.GetBusComp("MF Account Payable BC");
